    for (let i = 0; i <= 4; i++) { const v = v0 + ((vb - v0) * i) / 4; pts.push([uc * k - w / 2, uc * k + w / 2].map((u) => { const [x, z] = at(u, v); return [x, laneY(u, v) + 0.009, z]; })); }
