      for (let i = 0; i < stops.length; i++) { if (i) { const m = Math.ceil((stops[i] - stops[i - 1]) / stepMax); for (let j = 1; j < m; j++) add(stops[i - 1] + ((stops[i] - stops[i - 1]) * j) / m); } add(stops[i]); }
